int process_diag_message(struct sk_buff *skb, struct nlmsghdr *nlh) {
    struct sock_diag_handler *handler;

    if (nlh->nlmsg_len < NLMSG_HDRLEN)
        return -EINVAL;

    handler = find_diag_handler(nlh->nlmsg_type);
    if (!handler)
        return -ENOENT;

    if (handler->family != AF_UNSPEC && skb->sp->protinfo.af_inet.family != handler->family)
        return -EAFNOSUPPORT;

    if (!try_module_get(handler->owner))
        return -EINVAL;

    skb->sk = handler->sk;
    skb->destructor = handler->destructor;

    int ret = handler->dump(skb, nlh);

    module_put(handler->owner);
    return ret;
}

int process_socket_diag_message(struct sk_buff *skb, struct nlmsghdr *nlh) {
    int ret = -EINVAL;

    if (nlh->nlmsg_len < NLMSG_HDRLEN)
        return ret;

    struct sock_diag_handler *handler = find_sock_diag_handler(nlh);
    if (!handler)
        return ret;

    if (!handler->family || handler->family > AF_MAX)
        return ret;

    if (!try_module_get(handler->owner))
        return -ENOENT;

    if (handler->dump) {
        ret = handler->dump(skb, nlh);
        module_put(handler->owner);
        return ret;
    }

    module_put(handler->owner);
    return -EOPNOTSUPP;
}

int process_diag_message(struct sk_buff *skb, struct nlmsghdr *nlh) {
    int family;
    int (*dump_func)(struct sk_buff *, struct nlmsghdr *);
    int ret = -EINVAL;

    if (nlh->nlmsg_len < NLMSG_HDRLEN)
        return -EINVAL;

    family = ((struct diag_request *)NLMSG_DATA(nlh))->family;
    if (family < 0 || family >= AF_MAX)
        return -EINVAL;

    lock_diag_handler(family);
    dump_func = get_diag_dump_func(family);
    if (!dump_func) {
        unlock_diag_handler(family);
        return -EINVAL;
    }

    ret = dump_func(skb, nlh);
    unlock_diag_handler(family);

    return ret;
}

int process_diag_message(struct sk_buff *skb, struct nlmsghdr *nlh) {
    int ret = -EINVAL;

    if (nlh->nlmsg_len < NLMSG_HDRLEN)
        return ret;

    struct sock_diag_handler *handler = find_diag_handler(nlh);
    if (!handler)
        return ret;

    if (!is_valid_diag_family(nlh->nlmsg_type))
        return ret;

    lock_sock(handler->lock);

    ret = handler->dump(skb, nlh);

    unlock_sock(handler->lock);

    return ret;
}

int process_diag_message(struct sk_buff *skb, struct nlmsghdr *nlh) {
    int family;
    int (*dump)(struct sk_buff *, struct nlmsghdr *);
    struct sock_diag_handler *handler;

    if (nlh->nlmsg_len < NLMSG_HDRLEN)
        return -EINVAL;

    family = getsockopt_family(skb, nlh);
    if (family < 0)
        return family;

    handler = get_sock_diag_handler(family);
    if (!handler)
        return -EINVAL;

    if (!try_module_get(handler->owner))
        return -ENOMEM;

    dump = handler->dump;
    if (!dump) {
        module_put(handler->owner);
        return -EINVAL;
    }

    int res = dump(skb, nlh);
    module_put(handler->owner);
    return res;
}
